#[test]
fn total_width_never_exceeds_available() {
    let chassis = loudness_chassis();
    for w in [200.0, 400.0, 800.0, 1000.0, 1500.0, 2400.0_f32] {
        let solved = chassis.solve(w);
        // Total of visible widths must fit in available unless a
        // priority-1.0 section has been clipped (when w < mid's min_width).
        if w >= 280.0 {
            assert!(
                solved.total_width <= w + 0.5,
                "width={w}: total={} exceeded",
                solved.total_width
            );
        }
    }
}

#[test]
fn ties_drop_later_index_first() {
    // Two sections with the same priority — the later one should drop first.
    let chassis = ChassisLayout::new(
        HeaderSpec {
            brand_mark: String::new(),
            title: String::new(),
            subtitle: String::new(),
        },
        vec![
            section("a", "A", 200.0, 200.0, 0.5),
            section("b", "B", 200.0, 200.0, 1.0), // primary
            section("c", "C", 200.0, 200.0, 0.5),
        ],
    );
    // Total min = 600; available 400 forces one drop.
    let solved = chassis.solve(400.0);
    assert!(solved.section("a").unwrap().visible);
    assert!(solved.section("b").unwrap().visible);
    assert!(!solved.section("c").unwrap().visible);
}

#[test]
fn nan_priority_treated_as_never_collapse() {
    // NaN priority should be treated as 1.0 (never collapse).
    let chassis = ChassisLayout::new(
        HeaderSpec {
            brand_mark: String::new(),
            title: String::new(),
            subtitle: String::new(),
        },
        vec![
            section("a", "A", 200.0, 200.0, 0.5),
            section("b", "B", 200.0, 200.0, f32::NAN), // should behave like primary
        ],
    );
    // Total min = 400; available 300 forces a drop.
    let solved = chassis.solve(300.0);
    assert!(
        solved.section("b").unwrap().visible,
        "NaN priority section should remain visible"
    );
    assert!(
        !solved.section("a").unwrap().visible,
        "lower-priority section should be dropped"
    );
}

#[test]
fn clipped_total_width_never_exceeds_available() {
    // One protected section remains visible but its min_width exceeds available_width.
    let chassis = ChassisLayout::new(
        HeaderSpec {
            brand_mark: String::new(),
            title: String::new(),
            subtitle: String::new(),
        },
        vec![
            section("a", "A", 200.0, 200.0, 0.5), // collapsible
            section("b", "B", 280.0, 280.0, 1.0), // primary, never collapse
        ],
    );
    // Total min = 480; available 100 → a drops, b stays but min_sum > available.
    let solved = chassis.solve(100.0);
    assert!(!solved.section("a").unwrap().visible);
    assert!(solved.section("b").unwrap().visible);
    assert!(
        solved.total_width <= 100.0 + 0.01,
        "total_width={} exceeded available 100.0",
        solved.total_width
    );
    let sum: f32 = solved.visible().map(|s| s.width).sum();
    assert!(
        (sum - solved.total_width).abs() < 0.01,
        "total_width should equal sum of visible widths"
    );
}
